mapper.select:

WHERE s.ASSIGNEE_USERNAME = #{assigneeUsername}

    AND s.COMPLETED_AT >= #{startDate}


    AND s.COMPLETED_AT < DATE_ADD(#{endDate}, INTERVAL 1 DAY)

ORDER BY s.COMPLETED_AT DESC




        AND s.ASSIGNEE_USERNAME = #{assigneeUsername}


        AND u.DEPARTMENT_CODE = #{deptCode}


        AND i.BOARD_ID = #{boardId}


        AND s.COMPLETED_AT >= #{startDate}


        AND s.COMPLETED_AT < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


        AND s.APPROVAL_STATUS = #{approvalStatus}


        AND s.BASE_GRADE = #{baseGrade}


ORDER BY

    s.FINAL_SCORE

        CASE s.BASE_GRADE
            WHEN 'PERFECT' THEN 1
            WHEN 'EXCELLENT' THEN 2
            WHEN 'GOOD' THEN 3
            WHEN 'FAIR' THEN 4
            WHEN 'POOR' THEN 5
        END

    s.COMPLETED_AT

ASC
DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM TB_ITEM_SCORE s
LEFT JOIN TB_ITEM i ON s.ITEM_ID = i.ITEM_ID
LEFT JOIN TB_USER u ON s.ASSIGNEE_USERNAME = u.USERNAME


        AND s.ASSIGNEE_USERNAME = #{assigneeUsername}


        AND u.DEPARTMENT_CODE = #{deptCode}


        AND i.BOARD_ID = #{boardId}


        AND s.COMPLETED_AT >= #{startDate}


        AND s.COMPLETED_AT < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


        AND s.APPROVAL_STATUS = #{approvalStatus}


        AND s.BASE_GRADE = #{baseGrade}

SELECT s.ASSIGNEE_USERNAME, u.NAME AS ASSIGNEE_NAME, COUNT(*) AS COMPLETED_COUNT, SUM(s.FINAL_SCORE) AS TOTAL_SCORE, AVG(s.FINAL_SCORE) AS AVERAGE_SCORE, SUM(CASE WHEN s.BASE_GRADE = 'PERFECT' THEN 1 ELSE 0 END) AS PERFECT_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'EXCELLENT' THEN 1 ELSE 0 END) AS EXCELLENT_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'GOOD' THEN 1 ELSE 0 END) AS GOOD_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'FAIR' THEN 1 ELSE 0 END) AS FAIR_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'POOR' THEN 1 ELSE 0 END) AS POOR_COUNT, AVG(s.DIFFICULTY) AS AVERAGE_DIFFICULTY, AVG(s.WEIGHT_FACTOR) AS AVERAGE_WEIGHT_FACTOR FROM TB_ITEM_SCORE s LEFT JOIN TB_USER u ON s.ASSIGNEE_USERNAME = u.USERNAME WHERE s.ASSIGNEE_USERNAME = #{assigneeUsername}
AND s.COMPLETED_AT >= #{startDate}
AND s.COMPLETED_AT < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY s.ASSIGNEE_USERNAME, u.NAME

SELECT s.ASSIGNEE_USERNAME, u.NAME AS ASSIGNEE_NAME, COUNT(*) AS COMPLETED_COUNT, SUM(s.FINAL_SCORE) AS TOTAL_SCORE, AVG(s.FINAL_SCORE) AS AVERAGE_SCORE, SUM(CASE WHEN s.BASE_GRADE = 'PERFECT' THEN 1 ELSE 0 END) AS PERFECT_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'EXCELLENT' THEN 1 ELSE 0 END) AS EXCELLENT_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'GOOD' THEN 1 ELSE 0 END) AS GOOD_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'FAIR' THEN 1 ELSE 0 END) AS FAIR_COUNT, SUM(CASE WHEN s.BASE_GRADE = 'POOR' THEN 1 ELSE 0 END) AS POOR_COUNT, AVG(s.DIFFICULTY) AS AVERAGE_DIFFICULTY, AVG(s.WEIGHT_FACTOR) AS AVERAGE_WEIGHT_FACTOR FROM TB_ITEM_SCORE s LEFT JOIN TB_USER u ON s.ASSIGNEE_USERNAME = u.USERNAME WHERE u.DEPARTMENT_CODE = #{deptCode}
AND s.COMPLETED_AT >= #{startDate}
AND s.COMPLETED_AT < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY s.ASSIGNEE_USERNAME, u.NAME ORDER BY TOTAL_SCORE DESC


WHERE s.APPROVAL_STATUS = 'PENDING'

    AND u.DEPARTMENT_CODE = #{deptCode}

ORDER BY s.CREATED_AT ASC
